#!/usr/bin/env python3
"""Live browser trap UI, interaction, persistence and render integration checks."""
import json, sys, traceback
from pathlib import Path
from playwright.sync_api import sync_playwright
out=Path('docs/screenshots/traps'); out.mkdir(parents=True,exist_ok=True)
checks={}; errors=[]
def check(k,v):
 checks[k]=bool(v); print(k, bool(v),flush=True)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--enable-unsafe-swiftshader','--use-angle=swiftshader','--disable-dev-shm-usage'])
 page=b.new_page(viewport={'width':1280,'height':720});page.on('pageerror',lambda e:errors.append(str(e)))
 try:
  page.goto('http://127.0.0.1:5173/',wait_until='domcontentloaded');page.locator('#newgame').wait_for(state='visible',timeout=120000);page.click('#newgame');page.wait_for_function('game.started && document.pointerLockElement===game.canvas',timeout=60000)
  page.evaluate('''() => {const g=game,w=g.world,p=g.player.pos;g.renderer.setAnimationLoop(null);g.qualityLevel=3;g.aoOn=false;g.shaftsOn=false;g.onResize();g.ao.configuration.intensity=0;g.step(.016);let X=Math.floor(p.x)+12,Z=Math.floor(p.z)-12,Y=0;w.generateAround(X,Z,3);for(let x=X-14;x<=X+14;x+=3)for(let z=Z-14;z<=Z+14;z+=3)Y=Math.max(Y,w.surfaceY(x,z));Y+=3;for(let x=X-14;x<=X+14;x++)for(let z=Z-14;z<=Z+14;z++){w.set(x,Y-1,z,1);for(let y=Y;y<=Y+12;y++)w.set(x,y,z,0)}w.rebuildAround(X,Z,2);window.site={X,Y,Z};p.set(X-5,Y,Z+6);g.player.vel.set(0,0,0);g.entities.enemies=[];Object.assign(g.inv,{metal:100,stone:100,wood:100,goo:100,spikeTrap:3,trapdoor:3,arrowTrap:3,flameTrap:3,blastMine:3})}''')
  page.keyboard.press('Tab');page.wait_for_function('game.ui.craftOpen');check('five trap picker choices',page.locator('#trap-picker [data-trap]').count()==5);page.locator('#trap-picker [data-trap="flame"]').click();check('picker equips flame',page.evaluate('game.trapId==="flame"'))
  page.keyboard.press('Tab');page.wait_for_function('!game.ui.craftOpen && document.pointerLockElement===game.canvas')
  page.evaluate('''() => {const g=game,{X,Y,Z}=site;g.hover={x:X,y:Y-1,z:Z,nx:0,ny:1,nz:0};g.updateActions(.016)}''');page.keyboard.press('KeyR');page.evaluate('game.updateActions(.016)');check('R rotates directional wedge',page.evaluate('game.defenseRotation===1 && game.trapDirection.visible && Math.abs(game.trapDirection.rotation.y-Math.PI/2)<.001'))
  page.evaluate('''() => {const {X,Y,Z}=site;game.world.set(X,Y-1,Z,0);game.fireCd=0;game.hover={x:X,y:Y-1,z:Z,nx:0,ny:1,nz:0}}''');page.mouse.down();page.evaluate('game.updateActions(.016)');page.mouse.up();check('failed click spends nothing',page.evaluate('game.inv.flameTrap===3 && game.traps.traps.length===0'))
  page.evaluate('''() => {const {X,Y,Z}=site;game.world.set(X,Y-1,Z,1);game.fireCd=0;game.hover={x:X,y:Y-1,z:Z,nx:0,ny:1,nz:0}}''');page.mouse.down();page.evaluate('game.updateActions(.016)');page.mouse.up();check('successful click spends one and preserves rotation',page.evaluate('game.inv.flameTrap===2 && game.traps.traps.length===1 && game.traps.traps[0].rotation===1'))
  page.evaluate('''() => {const g=game,p=g.player.pos,w=g.world,c=[Math.floor(p.x)+1,Math.floor(p.y),Math.floor(p.z)];w.set(...c,3);g.construction.benches.push({cell:c,block:3})}''');page.keyboard.press('Tab');page.wait_for_function('game.ui.craftOpen');page.locator('#craftlist .recipe').filter(has_text='Flame trap').click();check('workbench recipe spends exact resources and equips',page.evaluate('game.inv.metal===94 && game.inv.stone===98 && game.inv.flameTrap===3 && game.trapId==="flame"'));page.keyboard.press('Tab');page.wait_for_function('!game.ui.craftOpen && document.pointerLockElement===game.canvas');page.evaluate('game.construction.benches.pop()')
  page.evaluate('''() => {const g=game,w=g.world,{X:x,Y:y,Z:z}=site;g.traps.restore([]);w.set(x,y-1,z,0);w.set(x+1,y,z,1);g.traps.place('trapdoor',0,x,y,z);g.player.pos.set(x+.5,y,z-2);g.player.aimDir.set(0,-.9,2.5).normalize()}''');page.keyboard.press('KeyE');check('E opens trapdoor',page.evaluate('game.traps.traps[0].open && game.world.get(site.X,site.Y,site.Z)===0'));page.keyboard.press('KeyE');check('E closes trapdoor',page.evaluate('!game.traps.traps[0].open && game.world.get(site.X,site.Y,site.Z)===8'))
  page.keyboard.press('KeyE');page.evaluate('''() => {const {X:x,Y:y,Z:z}=site;window.blocker=game.entities.spawnEnemy('zombie',x+.5,y,z+.5)}''');page.keyboard.press('KeyE');check('actor blocks closing',page.evaluate('game.traps.traps[0].open'));page.evaluate('blocker.dead=true');page.keyboard.press('KeyE');check('closing succeeds after actor leaves',page.evaluate('!game.traps.traps[0].open'))
  page.evaluate('''() => {const {X:x,Y:y,Z:z}=site;for(let y0=y;y0<=y+2;y0++)game.world.set(x,y0,z-1,3)}''');page.keyboard.press('KeyE');check('wall blocks E',page.evaluate('!game.traps.traps[0].open'));page.evaluate('''() => {const {X:x,Y:y,Z:z}=site;for(let y0=y;y0<=y+2;y0++)game.world.set(x,y0,z-1,0)}''')
  page.evaluate('''() => {const g=game,w=g.world,{X:x,Y:y,Z:z}=site;g.traps.restore([]);w.set(x,y,z,0);w.set(x,y-1,z,1);w.set(x+1,y,z,0);g.traps.place('arrow',0,x,y,z);g.traps.place('arrow',0,x,y,z+1);g.traps.traps.forEach(t=>t.ammo=0);g.inv.ammo=10;g.player.pos.set(x+.5,y-.9,z-1.5);g.player.aimDir.set(0,0,1)}''');page.keyboard.press('KeyE');check('E selects nearest aligned trap',page.evaluate('game.traps.traps[0].ammo===10 && game.traps.traps[1].ammo===0'))
  page.evaluate('''() => {const g=game,w=g.world,{X:x,Y:y,Z:z}=site;g.traps.restore([]);w.set(x,y,z,0);w.set(x,y-1,z,1);w.set(x+1,y,z,0);g.traps.place('flame',0,x,y,z);g.entities.enemies=[];g.entities.spawnEnemy('zombie',x+.5,y,z+4.5);g.traps.update(.1);g.player.pos.set(x+7,y+4,z-5);let p=g.player.pos,dx=x+.5-p.x,dy=y+.7-(p.y+1.55),dz=z+2-p.z;g.camYaw=g.camYawT=Math.atan2(-dx,-dz);g.camPitch=Math.atan2(dy,Math.hypot(dx,dz));g.updateCamera(0);g.updateAim();g.updateActions(0);g.ui.update(0);g.camera.updateMatrixWorld();g.composer.render()}''');check('flame fires visible model',page.evaluate('game.traps.flames.length>0 && game.traps.traps[0].model.visible'));page.screenshot(path=str(out/'02-integration.jpg'),type='jpeg',quality=90,timeout=90000)
  page.evaluate('''() => {const g=game,w=g.world,{X:x,Y:y,Z:z}=site;g.traps.restore([]);g.entities.enemies=[];w.set(x,y-1,z,0);w.set(x+1,y,z,1);g.traps.place('trapdoor',2,x,y,z);g.player.pos.set(x+.5,y,z-2);g.player.aimDir.set(0,-.9,2.5).normalize();g.traps.interact();g.traps.place('arrow',1,x+3,y,z);g.traps.traps[1].ammo=7;g.save('manual')}''');page.wait_for_function('!game.saving',timeout=60000);page.evaluate('game.quickLoad()');page.wait_for_function("game.traps.traps.length===2 && game.traps.traps[1].id==='arrow'",timeout=60000);check('IndexedDB save restores mixed traps and state',page.evaluate("game.traps.traps[0].id==='trapdoor' && game.traps.traps[0].rotation===2 && game.traps.traps[0].open && game.traps.traps[1].rotation===1 && game.traps.traps[1].ammo===7"))
  page.evaluate('''async () => {const db=await new Promise((ok,no)=>{const r=indexedDB.open('blockfall-isle',1);r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)});const data=await new Promise(ok=>{const r=db.transaction('saves').objectStore('saves').get('manual');r.onsuccess=()=>ok(r.result)});delete data.traps;delete data.glowsticks;await new Promise(ok=>{const tx=db.transaction('saves','readwrite');tx.objectStore('saves').put(data,'manual');tx.oncomplete=ok});db.close();game.quickLoad()}''');page.wait_for_function('game.traps.traps.length===0',timeout=60000);check('legacy save missing traps and glowsticks loads empty',page.evaluate('game.traps.traps.length===0 && game.glowsticks.sticks.length===0'));check('no browser errors',not errors)
 except Exception: errors.append(traceback.format_exc());print(errors[-1],flush=True)
 finally:
  (out/'results-integration.json').write_text(json.dumps({'checks':checks,'errors':errors},indent=2)+'\n');b.close()
if errors or not all(checks.values()):sys.exit(1)
